const dns = require("node:dns");

dns.setServers(["8.8.8.8", "8.8.4.4"]);

const express = require("express");
const cors = require("cors");
const dotenv = require("dotenv");
const { MongoClient } = require("mongodb");
const contactsRouter = require("./routes/contacts");


dotenv.config();

const app = express();
const PORT = 8080;

app.use(cors());
app.use("/contacts", contactsRouter);

const client = new MongoClient(process.env.MONGODB_URI);

async function connectToDatabase() {
    try {
        await client.connect();

        const db = client.db("cse341");
        app.locals.db = db;

        console.log("Connected to MongoDB Atlas");
    } catch (error) {
        console.error("MongoDB connection failed:", error);
    }
}

connectToDatabase();

app.get("/professional", (req, res) => {
    res.json({
        professionalName: "Emerald Awoke",
        base64Image: "",
        nameLink: {
            firstName: "Emerald",
            url: "https://github.com/"
        },
        primaryDescription: "I am a web development student learning how to build websites, APIs, and web applications.",
        workDescription1: "I enjoy learning programming and developing my skills with HTML, CSS, JavaScript, Node.js, and other web technologies.",
        workDescription2: "My goal is to continue improving my software development skills and create useful applications that solve real-world problems.",
        linkTitleText: "Find Me Online",
        linkedInLink: {
            text: "LinkedIn",
            link: "https://www.linkedin.com/"
        },
        githubLink: {
            text: "GitHub",
            link: "https://github.com/"
        }
    });
});

app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
});